package blockbranch.client.realistic;
import java.nio.file.*;import net.minecraft.core.*;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import net.minecraft.client.gui.screens.TitleScreen;import blockbranch.realistic.*;
/** Native resident hut views; no review-only terrain excavation or structure replacement. */
public final class WetlandHutView {
 private static boolean opened,saving;private static volatile boolean posed;private static volatile int view;private static int settled;private static long began;private static WetlandHuts.Plan target;
 public static void register(){
  ServerTickEvents.END_SERVER_TICK.register(server->{if(server.isDedicatedServer()||posed||server.getPlayerList().getPlayers().isEmpty())return;try{
   var player=server.getPlayerList().getPlayers().getFirst();var level=server.overworld();var g=(RealisticGenerator)level.getChunkSource().getGenerator();var q=Files.readString(Path.of(System.getProperty("blockbranch.wetlandHutMarker"))).trim().split(",");
   target=new WetlandHuts.Plan(Integer.parseInt(q[0]),Integer.parseInt(q[1]),Integer.parseInt(q[2]),Integer.parseInt(q[3]),Integer.parseInt(q[4]),0);
   if(view==3){int firstVariant=target.variant();target=g.wetlandHuts(level.getChunkSource().randomState()).plans().stream().filter(p->p.variant()!=firstVariant&&Math.abs(p.x())<1700000&&Math.abs(p.z())<1700000).min(java.util.Comparator.comparingDouble(p->Math.hypot(p.x(),p.z()))).orElseThrow();}
   var chunk=level.getChunk(target.x()>>4,target.z()>>4);var holder=level.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).getOrThrow(net.minecraft.world.level.levelgen.structure.BuiltinStructures.SWAMP_HUT);var piece=level.structureManager().getStartForStructure(holder.value(),chunk).getPieces().getFirst();var access=(WetlandHutAccess)piece;
   var commands=server.getCommands();var source=server.createCommandSourceStack();commands.performPrefixedCommand(source,"time set 6000");commands.performPrefixedCommand(source,"weather clear");commands.performPrefixedCommand(source,"gamemode creative "+player.getName().getString());
   var outside=access.blockbranch$local(3,0,-1);double ax=outside.getX()+.5,az=outside.getZ()+.5,floor=Double.NaN;
   for(int y=target.y()+3;y>=target.y()-4;y--){var p=new BlockPos(outside.getX(),y,outside.getZ());var shape=level.getBlockState(p).getCollisionShape(level,p);if(!shape.isEmpty()){floor=y+shape.max(Direction.Axis.Y);break;}}
   if(!Double.isFinite(floor))throw new AssertionError("Grounded hut approach");player.setPos(ax,floor,az);player.getAbilities().flying=false;player.onUpdateAbilities();var inside=access.blockbranch$local(3,0,3);double dx=inside.getX()-outside.getX(),dz=inside.getZ()-outside.getZ(),length=Math.hypot(dx,dz);
   for(int step=0;step<24;step++)player.move(net.minecraft.world.entity.MoverType.SELF,new net.minecraft.world.phys.Vec3(dx/length*.25,-.08,dz/length*.25));
   if(Math.hypot(player.getX()-ax,player.getZ()-az)<3.5||player.getY()<target.y()+1.9)throw new AssertionError("Native collision can walk from bank through both porch steps into hut: travel="+Math.hypot(player.getX()-ax,player.getZ()-az)+" feet="+player.getY());
   player.getAbilities().flying=true;player.onUpdateAbilities();
   // Native crafting interaction; the cauldron stays ordinary and unlit.
   var table=access.blockbranch$local(2,2,6);player.setPos(table.getX()+1.5,table.getY(),table.getZ()+.5);player.gameMode.useItemOn(player,level,player.getMainHandItem(),net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(table),Direction.UP,table,false));
   if(player.containerMenu==player.inventoryMenu)throw new AssertionError("Native crafting table opens");player.closeContainer();
   var cauldron=access.blockbranch$local(4,2,6);player.setPos(cauldron.getX()+1.5,cauldron.getY(),cauldron.getZ()+.5);player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.WATER_BUCKET));
   player.gameMode.useItemOn(player,level,player.getMainHandItem(),net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(cauldron),Direction.UP,cauldron,false));
   if(!level.getBlockState(cauldron).is(net.minecraft.world.level.block.Blocks.WATER_CAULDRON))throw new AssertionError("Native bucket fills cauldron");player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.BUCKET));
   player.gameMode.useItemOn(player,level,player.getMainHandItem(),net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(cauldron),Direction.UP,cauldron,false));
   if(!level.getBlockState(cauldron).is(net.minecraft.world.level.block.Blocks.CAULDRON))throw new AssertionError("Native bucket empties cauldron");player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,net.minecraft.world.item.ItemStack.EMPTY);
   BlockPos camera=view==4?access.blockbranch$local(3,5,-10):view==1?access.blockbranch$local(-13,8,18):view==2?access.blockbranch$local(3,2,1):access.blockbranch$local(14,8,-14);var aim=view==2?access.blockbranch$local(3,2,6):access.blockbranch$local(3,3,4);double cx=camera.getX()+.5,cy=camera.getY(),cz=camera.getZ()+.5;dx=aim.getX()+.5-cx;dz=aim.getZ()+.5-cz;double dy=aim.getY()+.5-(cy+player.getEyeHeight());double yaw=Math.toDegrees(Math.atan2(-dx,dz)),pitch=Math.toDegrees(Math.atan2(-dy,Math.hypot(dx,dz)));
   commands.performPrefixedCommand(source,"tp "+player.getName().getString()+" "+cx+" "+cy+" "+cz+" "+yaw+" "+pitch);posed=true;
  }catch(Throwable e){blockbranch.Blockbranch.LOGGER.error("WETLAND_HUT_VIEW_FAIL",e);try{Files.writeString(Path.of(System.getProperty("blockbranch.wetlandHutResult")),"FAIL "+e);}catch(Exception ignored){}server.halt(false);}});
  ClientTickEvents.END_CLIENT_TICK.register(client->{try{
   if(opened&&System.nanoTime()-began>600_000_000_000L){Files.writeString(client.gameDirectory.toPath().resolve("result.txt"),"FAIL native hut view timeout");client.stop();return;}
   if(!opened&&client.gui.screen() instanceof TitleScreen){opened=true;began=System.nanoTime();client.createWorldOpenFlows().openWorld("WetlandHutReview",()->client.gui.setScreen(new TitleScreen()));return;}
   if(Files.exists(client.gameDirectory.toPath().resolve("result.txt"))){client.stop();return;}
   if(!posed||client.level==null||client.player==null||saving)return;client.options.fov().set(view==2?65:50);if(!client.gui.hud.isHidden())client.gui.hud.toggle();client.gui.toastManager().clear();var area=client.levelRenderer.viewArea();if(area==null)return;
   int count=0;for(int z=-2;z<=2;z++)for(int x=-2;x<=2;x++){boolean visible=false;for(int dy:new int[]{-16,0,16}){var section=area.getRenderSectionAt(new BlockPos((target.x()>>4)*16+x*16+8,target.y()+3+dy,(target.z()>>4)*16+z*16+8));visible|=section!=null&&section.getSectionMesh().hasRenderableLayers();}if(visible)count++;}if(count<20){settled=0;return;}if(++settled<120)return;saving=true;
   String name=new String[]{"wetland-hut-front.png","wetland-hut-rear.png","wetland-hut-interior.png","wetland-hut-alternate.png","wetland-hut-porch.png"}[view];net.minecraft.client.Screenshot.grab(client.gameDirectory,name,client.gameRenderer.mainRenderTarget(),1,message->client.execute(()->{try{if(view<4){view++;settled=0;saving=false;posed=false;}else{Files.writeString(client.gameDirectory.toPath().resolve("result.txt"),"PASS native hut views, both natural variants, walked entrance, native crafting interaction");client.stop();}}catch(Exception e){throw new RuntimeException(e);}}));
  }catch(Throwable e){blockbranch.Blockbranch.LOGGER.error("WETLAND_HUT_CLIENT_FAIL",e);client.stop();}});
 }
}
